// === Mapping Agenda Ludomobile -> Registre ===
// Entree principale : evenements Google Calendar (Get Many, recurrents deplies)
// Lignes existantes du Registre : via $('Registre - Lire').all()

// 1) Index des lignes existantes par ID_Event
const existing = {};
for (const row of $('Registre - Lire').all()) {
  const r = row.json || {};
  const id = r.ID_Event;
  if (id !== undefined && id !== null && String(id).trim() !== '') {
    existing[String(id).trim()] = r;
  }
}

// 2) Annuaire participants (email -> nom)
const ANNUAIRE = {
  'jerome@venividiludi.fr': 'Jérôme',
  'alice@venividiludi.fr': 'Alice',
  'angelique@venividiludi.fr': 'Angélique',
  'corentin@venividiludi.fr': 'Corentin',
  'william@venividiludi.fr': 'William',
  'valentain@venividiludi.fr': 'Valentain',
  'claudine@venividiludi.fr': 'Claudine',
  'sonia@venividiludi.fr': 'Sonia',
  'jean@venividiludi.fr': 'Jean',
  'duntzkilian2711@gmail.com': 'Kilian Duntz',
  'mathisnatov@gmail.com': 'Mathis Natov',
  'kevinjrtiktok@gmail.com': 'Kevin',
  'okodasoandre@gmail.com': 'André Okodosa',
  'totoandzwan@gmail.com': 'André Okodosa',
  'katieflandrin13@gmail.com': 'Katie Flandrin'
};
const IGNORE = 'contact@venividiludi.fr';

// --- Helpers ---
const stripEmojis = (s) => String(s || '')
  .replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{2B00}-\u{2BFF}\u{2190}-\u{21FF}\u{FE00}-\u{FE0F}\u{200D}]/gu, '')
  .replace(/[✅🎲]/gu, '');

function cleanTitre(summary) {
  let t = stripEmojis(summary);
  t = t.replace(/\[PROVISOIRE\]/gi, '');
  t = t.replace(/VVL\s*[–—-]\s*/g, '');      // "VVL –", "VVL —", "VVL -"
  t = t.replace(/\s{2,}/g, ' ').trim();
  t = t.replace(/^[–—\-\/\s]+/, '').trim();   // tirets/slash residuels en tete
  return t;
}

function dateDebut(ev) {
  const raw = (ev.start && (ev.start.dateTime || ev.start.date)) || '';
  return String(raw).slice(0, 10);
}

function statutResa(ev) {
  if (ev.status === 'cancelled') return 'Annulé';
  const sum = ev.summary || '';
  const desc = ev.description || '';
  if (/\[PROVISOIRE\]/i.test(sum) || /en attente de signature/i.test(desc)) return 'Provisoire';
  return 'Confirmé';
}

function devis(desc) {
  const m = String(desc || '').match(/D-20\d{2}-\d+(?:-\d+)?|O-20\d{2}-\d+(?:-\d+)?|DE\d+/);
  return m ? m[0] : '';
}

function intervenants(ev) {
  const att = ev.attendees || [];
  const noms = [];
  for (const a of att) {
    const email = String(a.email || '').toLowerCase().trim();
    if (!email || email === IGNORE) continue;
    if (a.resource) continue;            // salles / ressources
    if (a.self) continue;                // le calendrier lui-meme
    const nom = ANNUAIRE[email] || email.split('@')[0];
    if (!noms.includes(nom)) noms.push(nom);
  }
  return noms.join(', ');
}

function emailContact(desc) {
  const emails = (String(desc || '').match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g) || [])
    .map((e) => e.trim())
    .filter((e) => e.toLowerCase() !== IGNORE);
  return emails.length ? emails[0] : '';
}

function partenaire(ev) {
  const sum = cleanTitre(ev.summary || '');
  // "Mairie de X / Animation..." -> avant le 1er separateur " / ", " – ", " — "
  const p = sum.split(/\s[\/–—]\s/)[0].trim();
  return p || '';
}

// --- Boucle sur les evenements ---
const out = [];
for (const item of $input.all()) {
  const ev = item.json || {};
  if (!ev.id) continue;
  const id = String(ev.id).trim();
  const prev = existing[id];

  const row = {
    ID_Event: id,
    Statut_Resa: statutResa(ev),
    Date: dateDebut(ev),
    Titre: cleanTitre(ev.summary || ''),
    // Partenaire / Email_Contact : on conserve la valeur existante (souvent affinee a la main),
    // sinon extraction depuis la description. -> voir note workflow si vous preferez toujours re-extraire.
    Partenaire: (prev && prev.Partenaire) ? prev.Partenaire : partenaire(ev),
    Email_Contact: (prev && prev.Email_Contact) ? prev.Email_Contact : emailContact(ev.description),
    N_Devis: devis(ev.description),
    Lieu_Animation: ev.location || '',
    Intervenants_Agenda: intervenants(ev),
    // Champs "agent" : CONSERVES si la ligne existe, sinon valeurs par defaut
    Statut_Fiche: prev ? (prev.Statut_Fiche || 'À préparer') : 'À préparer',
    Lien_Fiche: prev ? (prev.Lien_Fiche || '') : '',
    // routage upsert (jamais de suppression)
    _isUpdate: !!prev
  };
  out.push({ json: row });
}

return out;
